package i18n

// Тексты сетевой нагрузки и признаков атаки (internal/netload):
// признаки (rule.net_*), факты (ev.net_*) и подписи вкладки
// «Сетевая нагрузка». Формулировки — «признак/требует проверки»:
// те же симптомы даёт наплыв настоящих посетителей или зависшее
// приложение.
func init() {
	add(map[string]entry{
		// Признаки (таблица 16.3 плана).
		"rule.net_syn_flood.title":      {"Признаки SYN-флуда: {0} SYN cookies/с", "Signs of a SYN flood: {0} SYN cookies/s"},
		"rule.net_syn_flood.title_port": {"Много полуоткрытых соединений на порту {0}", "Many half-open connections on port {0}"},
		"rule.net_syn_flood.rec": {"Полуоткрытое соединение — это начатое и не завершённое рукопожатие. Их много либо при SYN-флуде, либо при массовых обрывах связи у клиентов. Проверьте: ss -tn state syn-recv | head и ss -s. Защита: net.ipv4.tcp_syncookies=1 (вкладка «Результаты аудита», группа «Ядро»), больший tcp_max_syn_backlog, у хостера — анти-DDoS. Блокировать адреса приложение не умеет и не будет: ufw limit и nginx limit_conn применяете вы.",
			"A half-open connection is a handshake that was started and never finished. Many of them mean either a SYN flood or mass connection drops on the client side. Check with: ss -tn state syn-recv | head and ss -s. Defenses: net.ipv4.tcp_syncookies=1 (Audit results tab, Kernel group), a larger tcp_max_syn_backlog, and anti-DDoS at your provider. The application cannot and will not block addresses: ufw limit and nginx limit_conn are yours to apply."},
		"rule.net_listen_overflow.title":      {"Соединения отбрасываются: {0}/с", "Connections are being dropped: {0}/s"},
		"rule.net_listen_overflow.title_port": {"Очередь принятия соединений на порту {0} переполнена", "The accept queue on port {0} is full"},
		"rule.net_listen_overflow.rec": {"Приложение не успевает принимать соединения — это бывает и при атаке, и при нехватке воркеров или ресурсов. Посмотрите очередь: ss -ltn (столбцы Recv-Q и Send-Q — очередь и backlog). Увеличьте число рабочих процессов приложения и его backlog (listen(…, backlog), в nginx — «listen … backlog=»), при необходимости net.core.somaxconn.",
			"The application is not accepting connections fast enough — that happens both under attack and when workers or resources run short. Look at the queue: ss -ltn (the Recv-Q and Send-Q columns are the queue and the backlog). Increase the number of application workers and its backlog (listen(…, backlog), “listen … backlog=” in nginx), and net.core.somaxconn if needed."},
		"rule.net_conn_flood_ip.title": {"С адреса {0} открыто {1} соединений", "Address {0} holds {1} connections"},
		"rule.net_conn_flood_ip.rec": {"Один адрес держит необычно много соединений. Это бывает и у своего прокси, монитора или CDN — такие сети впишите в SSG_NET_TRUSTED_NETS, и они перестанут считаться источниками. Если адрес чужой: ограничьте частоту (ufw limit <порт>/tcp) или число соединений в приложении (в nginx — limit_conn), при необходимости заблокируйте адрес сами. Приложение ничего не блокирует.",
			"A single address holds an unusually large number of connections. That also happens with your own proxy, monitor or CDN — put such networks into SSG_NET_TRUSTED_NETS and they will no longer count as sources. If the address is not yours: limit the rate (ufw limit <port>/tcp) or the number of connections in the application (limit_conn in nginx), and block the address yourself if needed. The application blocks nothing."},
		"rule.net_conn_flood_subnet.title": {"Из подсети {0} открыто {1} соединений", "Subnet {0} holds {1} connections"},
		"rule.net_conn_flood_subnet.rec": {"Соединения идут из одной подсети с нескольких адресов — так выглядит распределённая атака с одной сети или один клиент за NAT. Проверьте: ss -tn | awk '{print $5}' | cut -d: -f1 | sort | uniq -c | sort -rn | head. Ограничивать подсеть (ufw, nginx limit_conn по $binary_remote_addr) нужно вручную и аккуратно: под маску могут попасть обычные посетители.",
			"Connections come from one subnet through several addresses — that looks like a distributed attack from a single network, or one client behind NAT. Check with: ss -tn | awk '{print $5}' | cut -d: -f1 | sort | uniq -c | sort -rn | head. Restricting a subnet (ufw, nginx limit_conn by $binary_remote_addr) must be done by hand and carefully: ordinary visitors may fall under the mask."},
		"rule.net_conn_surge.title": {"Наплыв соединений: {0} входящих", "Surge of connections: {0} incoming"},
		"rule.net_conn_surge.rec": {"Входящих соединений заметно больше обычного для этого сервера. Это не обязательно атака: так же выглядит упоминание в новостях или запуск рассылки. Посмотрите, на какие порты и с каких адресов идут соединения, и выдержит ли приложение; при необходимости включите ограничение частоты.",
			"There are noticeably more incoming connections than usual for this server. It is not necessarily an attack: a mention in the news or a mailing campaign looks the same. See which ports and addresses the connections go to, and whether the application can take it; enable rate limiting if needed."},
		"rule.net_conntrack_full.title": {"Таблица conntrack заполнена на {0} %", "The conntrack table is {0}% full"},
		"rule.net_conntrack_full.rec": {"Когда таблица отслеживания соединений заполняется, ядро отбрасывает новые соединения — сервер «лежит» без всякой уязвимости, и в журнале ядра появляется «nf_conntrack: table full, dropping packet». Поднимите net.netfilter.nf_conntrack_max (каждая запись — около 300 байт) и hashsize, сократите таймауты (nf_conntrack_tcp_timeout_established), либо исключите часть трафика из conntrack (iptables -t raw … NOTRACK).",
			"When the connection tracking table fills up, the kernel drops new connections — the server goes down without any vulnerability involved, and the kernel log shows “nf_conntrack: table full, dropping packet”. Raise net.netfilter.nf_conntrack_max (about 300 bytes per entry) and hashsize, shorten the timeouts (nf_conntrack_tcp_timeout_established), or exclude some traffic from conntrack (iptables -t raw … NOTRACK)."},
		"rule.net_orphans_high.title": {"Много сокетов без владельца: {0}", "Many orphaned sockets: {0}"},
		"rule.net_orphans_high.rec": {"Сокеты, у которых уже нет процесса-владельца, занимают память ядра; при достижении tcp_max_orphans ядро начинает их убивать, и в журнале появляется «too many orphaned sockets». Обычно это следствие флуда или приложения, которое не закрывает соединения. Посмотрите ss -s и журнал ядра (journalctl -k).",
			"Sockets whose owning process is gone still take kernel memory; at tcp_max_orphans the kernel starts killing them and the log shows “too many orphaned sockets”. Usually this follows a flood or an application that does not close connections. Check ss -s and the kernel log (journalctl -k)."},
		"rule.net_udp_flood.title": {"Признаки UDP-флуда: {0} ошибок/с", "Signs of a UDP flood: {0} errors/s"},
		"rule.net_udp_flood.rec": {"Либо приложение не успевает читать UDP (растут RcvbufErrors — помогает больший буфер приёма: net.core.rmem_max и SO_RCVBUF в приложении), либо поток идёт на закрытые порты (NoPorts — ядро отвечает ICMP port unreachable, это зря расходует канал). Проверьте, какие UDP-порты открыты наружу (вкладка «Открытые порты»), и ограничьте их у хостера или межсетевым экраном.",
			"Either the application cannot read UDP fast enough (RcvbufErrors grow — a larger receive buffer helps: net.core.rmem_max and SO_RCVBUF in the application), or the flood goes to closed ports (NoPorts — the kernel answers ICMP port unreachable, wasting the link). Check which UDP ports are exposed (Open ports tab) and restrict them at the provider or in the firewall."},
		"rule.net_rx_drops.title": {"Пакеты отбрасываются на приёме: {0}/с", "Packets are dropped on receive: {0}/s"},
		"rule.net_rx_drops.rec": {"Ядро или сетевая карта не успевают обрабатывать пакеты. Посмотрите ip -s link и /proc/net/softnet_stat. Помогают больший буфер очереди (net.core.netdev_max_backlog), RPS/RSS по нескольким ядрам и достаточный CPU на softirq: при нехватке процессора одновременно растёт steal или time_squeeze.",
			"The kernel or the network card cannot keep up with the packets. Look at ip -s link and /proc/net/softnet_stat. A larger queue buffer (net.core.netdev_max_backlog), RPS/RSS across cores and enough CPU for softirq all help: when the CPU runs short, steal or time_squeeze grows at the same time."},
		"rule.net_pps_surge.title": {"Наплыв пакетов: {0}/с", "Packet surge: {0}/s"},
		"rule.net_pps_surge.rec": {"Справка: входящих пакетов намного больше обычного. Один такой признак атаку не доказывает — смотрите его вместе с остальными (полуоткрытые соединения, отбросы, conntrack). Объёмную атаку, которая забивает канал до сервера, изнутри не видно совсем: её видит только хостер.",
			"Note: there are far more incoming packets than usual. On its own this proves nothing — read it together with the others (half-open connections, drops, conntrack). A volumetric attack that saturates the link to the server is not visible from inside at all: only the provider sees it."},
		"rule.net_ddos_suspected.title": {"Похоже на DDoS: симптомы из {0} групп", "Looks like a DDoS: symptoms from {0} groups"},
		"rule.net_ddos_suspected.rec": {"Сработали признаки из разных групп одновременно — для наплыва настоящих посетителей это нетипично. Проверьте источники соединений и порты в этом разделе, убедитесь, что включены SYN cookies и хватает conntrack, и обратитесь к хостеру: объёмную атаку по каналу останавливают только на его стороне или на CDN. Приложение само ничего не блокирует.",
			"Findings from different groups fired at once, which is unusual for a surge of real visitors. Check the connection sources and ports in this section, make sure SYN cookies are on and conntrack is large enough, and contact your provider: a volumetric attack on the link can only be stopped on their side or at a CDN. The application blocks nothing by itself."},
		"rule.net_table_truncated.title": {"Таблица сокетов усечена", "The socket table was truncated"},
		"rule.net_table_truncated.rec": {"Соединений больше, чем предел SSG_NET_MAX_SOCKETS, поэтому числа в этом разделе занижены — это само по себе признак очень большого числа соединений. Предел защищает службу от исчерпания памяти; увеличивать его стоит с запасом по памяти (на сокет уходит около 200 байт).",
			"There are more connections than the SSG_NET_MAX_SOCKETS limit, so the numbers in this section are understated — which is itself a sign of a very large number of connections. The limit protects the service from running out of memory; raise it only with memory to spare (about 200 bytes per socket)."},

		// Факты признаков.
		"ev.net_cookies":        {"SYN cookies: {0}/с (пик {1}/с)", "SYN cookies: {0}/s (peak {1}/s)"},
		"ev.net_reqq_drop":      {"SYN отбрасываются: TCPReqQFullDrop {0}/с", "SYNs are dropped: TCPReqQFullDrop {0}/s"},
		"ev.net_cookies_off":    {"net.ipv4.tcp_syncookies = 0 — защита от SYN-флуда выключена", "net.ipv4.tcp_syncookies = 0 — SYN flood protection is off"},
		"ev.net_listen_drops":   {"ListenOverflows {0}/с, ListenDrops {1}/с, somaxconn {2}", "ListenOverflows {0}/s, ListenDrops {1}/s, somaxconn {2}"},
		"ev.net_conntrack":      {"conntrack {0} %: {1} из {2}", "conntrack {0}%: {1} of {2}"},
		"ev.net_conntrack_drop": {"ядро теряет соединения: drop {0}/с, early_drop {1}/с, insert_failed {2}/с", "the kernel is losing connections: drop {0}/s, early_drop {1}/s, insert_failed {2}/s"},
		"ev.net_orphans":        {"сокетов без владельца {0} из {1} (tcp_max_orphans)", "{0} orphaned sockets of {1} (tcp_max_orphans)"},
		"ev.net_abort_memory":   {"ядро закрывает сокеты из-за памяти: TCPAbortOnMemory {0}/с", "the kernel closes sockets out of memory: TCPAbortOnMemory {0}/s"},
		"ev.net_udp":            {"RcvbufErrors {0}/с, NoPorts {1}/с, InErrors {2}/с", "RcvbufErrors {0}/s, NoPorts {1}/s, InErrors {2}/s"},
		"ev.net_rx_drops":       {"отбросы интерфейсов {0}/с, softnet {1}/с при {2} пакетах/с", "interface drops {0}/s, softnet {1}/s at {2} packets/s"},
		"ev.net_time_squeeze":   {"time_squeeze {0}/с — не хватает процессора на обработку пакетов", "time_squeeze {0}/s — not enough CPU to process packets"},
		"ev.net_pps":            {"{0} пакетов/с против обычных {1} (×{2})", "{0} packets/s against the usual {1} (×{2})"},
		"ev.net_half_open":      {"полуоткрытых {0} при backlog {1} на порту {2}", "{0} half-open with backlog {1} on port {2}"},
		"ev.net_sources":        {"разных адресов: {0}", "distinct addresses: {0}"},
		"ev.net_accept_queue":   {"в очереди accept {0} из {1} на порту {2}", "{0} of {1} in the accept queue on port {2}"},
		"ev.net_conn_ip":        {"{0}: соединений {1} (порог {2}), порты: {3}", "{0}: {1} connections (threshold {2}), ports: {3}"},
		"ev.net_conn_half":      {"из них полуоткрытых: {0}", "of them half-open: {0}"},
		"ev.net_private":        {"адрес из частной сети: обычно это свой прокси или соседний контейнер", "the address is from a private network: usually your own proxy or a neighbouring container"},
		"ev.net_check_cmd":      {"проверить: ss -tn | grep {0}", "check with: ss -tn | grep {0}"},
		"ev.net_subnet":         {"{0}: соединений {1} с {2} адресов, порты: {3}", "{0}: {1} connections from {2} addresses, ports: {3}"},
		"ev.net_surge":          {"входящих соединений {0} против обычных {1} (×{2})", "{0} incoming connections against the usual {1} (×{2})"},
		"ev.net_truncated":      {"не разобрано сокетов: {0} (предел SSG_NET_MAX_SOCKETS)", "sockets not parsed: {0} (SSG_NET_MAX_SOCKETS limit)"},
		"ev.net_suspected":      {"одновременно: {0} — симптомы из {1} групп", "at the same time: {0} — symptoms from {1} groups"},
		"ev.net_volumetric":     {"объёмную атаку, которая забивает канал до сервера, изнутри не видно: её видит только хостер", "a volumetric attack that saturates the link to the server is invisible from inside: only the provider sees it"},

		// Названия рядов счётчиков ядра (ключи tui.m.* общие для
		// веб-панели и терминала, как у остальных метрик).
		"tui.m.net_syn_rate":     {"SYN cookies в секунду", "SYN cookies per second"},
		"tui.m.net_cookies_fail": {"Неудачных SYN cookies в секунду", "Failed SYN cookies per second"},
		"tui.m.net_listen_drops": {"Отбросов на слушающих сокетах в секунду", "Listen socket drops per second"},
		"tui.m.net_conntrack":    {"Заполненность conntrack, %", "Conntrack usage, %"},
		"tui.m.net_rx_drops":     {"Отбросов на приёме в секунду", "Receive drops per second"},
		"tui.m.net_udp_errors":   {"Ошибок UDP в секунду", "UDP errors per second"},
		"tui.m.net_estab":        {"Установленных соединений", "Established connections"},
		"tui.m.net_orphan":       {"Сокетов без владельца", "Orphaned sockets"},
		"tui.m.net_retrans":      {"Повторных передач в секунду", "Retransmits per second"},

		// Вкладка «Сетевая нагрузка» (веб) и панель терминала.
		"web.tab.netload": {"Сетевая нагрузка", "Network load"},
		"web.netload.hint": {"Нагрузка на сеть и признаки атаки: полуоткрытые соединения по портам, очередь принятия соединений, источники соединений, счётчики ядра и таблица conntrack. Только наблюдение: приложение не блокирует адреса и не меняет правила межсетевого экрана — команды в рекомендациях выполняете вы. Объёмную атаку, которая забивает канал до сервера, изнутри не видно совсем.",
			"Network load and signs of an attack: half-open connections per port, the accept queue, connection sources, kernel counters and the conntrack table. Observation only: the application does not block addresses and does not change firewall rules — the commands in the recommendations are yours to run. A volumetric attack that saturates the link to the server is not visible from inside at all."},
		"web.netload.disabled":      {"Наблюдение за сетевой нагрузкой выключено вместе с метриками (SSG_METRICS_ENABLED=false).", "Network load monitoring is disabled together with metrics (SSG_METRICS_ENABLED=false)."},
		"web.netload.empty":         {"Данных пока нет.", "No data yet."},
		"web.netload.when":          {"Снимок: {0} · входящих соединений: {1} · полуоткрытых: {2}", "Snapshot: {0} · incoming connections: {1} · half-open: {2}"},
		"web.netload.ok":            {"Признаков атаки нет", "No signs of an attack"},
		"web.netload.alerts":        {"Сработавшие признаки: {0}", "Active findings: {0}"},
		"web.netload.ports":         {"Порты", "Ports"},
		"web.netload.sources":       {"Источники соединений", "Connection sources"},
		"web.netload.counters":      {"Счётчики ядра", "Kernel counters"},
		"web.netload.trusted":       {"Доверенные сети (не считаются источниками флуда): {0}", "Trusted networks (never counted as flood sources): {0}"},
		"web.netload.no_baseline":   {"Базы «как обычно» ещё нет: нужно шесть часов метрик, пока работают только абсолютные пороги.", "There is no “usual” baseline yet: six hours of metrics are needed, so only absolute thresholds apply."},
		"web.netload.truncated":     {"Таблица сокетов усечена: не разобрано {0} сокетов, числа занижены.", "The socket table was truncated: {0} sockets were not parsed, the numbers are understated."},
		"web.stat.netload":          {"признаков сетевой нагрузки", "network load findings"},
		"web.col.source":            {"Источник", "Source"},
		"web.col.port":              {"Порт", "Port"},
		"web.netload.trusted_short": {"доверенная", "trusted"},
		"web.col.halfopen":          {"Полуоткрытых", "Half-open"},
		"web.col.estab":             {"Соединений", "Connections"},
		"web.col.queue":             {"Очередь accept", "Accept queue"},
		"web.col.backlog":           {"Backlog", "Backlog"},
		"web.col.sources":           {"Адресов", "Addresses"},
		"tui.panel.netload":         {"Сетевая нагрузка", "Network load"},
		"tui.cols.netload":          {"ПРОТ  ПОРТ   ПОЛУОТКР.  СОЕДИН.  ОЧЕРЕДЬ  ПРОЦЕСС", "PROTO PORT   HALF-OPEN  CONNS    QUEUE    PROCESS"},
		"tui.netload.when":          {"Снимок {0} · входящих {1} · полуоткрытых {2}", "Snapshot {0} · incoming {1} · half-open {2}"},
		"tui.netload.off":           {"Наблюдение за сетевой нагрузкой выключено (SSG_METRICS_ENABLED=false)", "Network load monitoring is disabled (SSG_METRICS_ENABLED=false)"},
		"tui.h.net_sources":         {"Источники соединений", "Connection sources"},
		"tui.h.net_counters":        {"Счётчики ядра", "Kernel counters"},
		"tui.net.summary":           {"сеть: входящих {0} · полуоткрытых {1}", "network: {0} incoming · {1} half-open"},
		"tui.net.alerts":            {"признаков атаки: {0}", "attack findings: {0}"},

		// Ошибка настройки.
		"err.env_nets": {"SSG_NET_TRUSTED_NETS: не удалось разобрать {0}", "SSG_NET_TRUSTED_NETS: failed to parse {0}"},
	})
}
